        .reset(reset),
        .data(data),
        .start_shifting(start_shifting)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to apply one bit of data synchronously
    task apply_bit(input b);
        begin
            @(posedge clk);
            #1; // small delay after clock edge to sample/drive cleanly
            data = b;
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 1;
        data = 0;

        // Hold reset for a couple of cycles
        @(posedge clk);
        @(posedge clk);
        #1;
        if (start_shifting !== 1'b0) errors = errors + 1;

        // Deassert reset
        reset = 0;
        @(posedge clk);

        // Test Case 1: Send incorrect stream first (e.g., 1000)
        apply_bit(1'b1);
        apply_bit(1'b0);
        apply_bit(1'b0);
        apply_bit(1'b0);
        #1;
