        apply_bit(1'b1); // Got '1101' -> should trigger start_shifting

        // Wait one clock edge for FSM transition to S_DONE
        @(posedge clk);
        #1;
        if (start_shifting !== 1'b1) errors = errors + 1;

        // Test Case 3: Verify start_shifting stays high forever (even with random data/zeros)
        apply_bit(1'b0);
        apply_bit(1'b0);
        #1;
        if (start_shifting !== 1'b1) errors = errors + 1;

        // Test Case 4: Synchronous reset check
        @(posedge clk);
        reset = 1;
        #1;
        if (start_shifting !== 1'b0) errors = errors + 1;

        @(posedge clk);
        reset = 0;
        #1;
        if (start_shifting !== 1'b0) errors = errors + 1;

        // Test Case 5: Overlapping sequence test ("11101")
        apply_bit(1'b1);
        apply_bit(1'b1);
        apply_bit(1'b1); // Should stay in S_11
        apply_bit(1'b0); // S_110
        apply_bit(1'b1); // S_DONE ("1101")

        @(posedge clk);
        #1;
        if (start_shifting !== 1'b1) errors = errors + 1;

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
